import React, { useState, useEffect } from 'react';
import api from '../services/api'; // Dùng trung tâm dữ liệu ní đã viết[cite: 50]

const Orders = () => {
    const [orders, setOrders] = useState([]);

    // 4 Trạng thái thầy yêu cầu + 1 trạng thái Hủy[cite: 43]
    const statusMap = {
        "Pending": { label: "Chờ xử lý", color: "bg-secondary" },
        "Processing": { label: "Chờ vận chuyển", color: "bg-info" },
        "Shipping": { label: "Đang vận chuyển", color: "bg-warning" },
        "Completed": { label: "Hoàn thành", color: "bg-success" },
        "Cancelled": { label: "Đã hủy", color: "bg-danger" }
    };

    const fetchOrders = async () => {
        try {
            // Gọi đúng endpoint /orders/all dành cho Admin
            const res = await api.get('/orders/all');
            console.log("Dữ liệu nhận được:", res.data); // Log để check nếu bảng vẫn trống

            // Backend của ní trả về List trực tiếp nên dùng res.data là đủ
            setOrders(res.data);
        } catch (err) {
            console.log("Lỗi tải đơn hàng:", err.response?.status);
        }
    };

    useEffect(() => { fetchOrders(); }, []);

    const updateStatus = async (id, newStatus) => {
        try {
            // Gửi trực tiếp chuỗi newStatus (ví dụ: "Shipping") lên server
            await api.put(`/orders/${id}/status`, { status: newStatus });
            alert("Đã chuyển trạng thái đơn hàng! 🚚");
            fetchOrders();
        } catch (err) {
            alert("Không cập nhật được! Kiểm tra lại API Backend nhé.");
        }
    };

    const handleStatusChange = async (orderId, currentStatus) => {
        // Xác định trạng thái tiếp theo (Logic đơn giản: Pending -> Shipping -> Completed)
        let nextStatus = '';
        if (currentStatus === 'Pending') nextStatus = 'Shipping';
        else if (currentStatus === 'Shipping') nextStatus = 'Completed';
        else return; // Đã Completed hoặc Canceled thì không chuyển nữa

        try {
            await ordersApi.updateStatus(orderId, nextStatus);

            // Cập nhật lại giao diện ngay lập tức mà không cần F5
            setOrders(prevOrders =>
                prevOrders.map(order =>
                    order.id === orderId ? { ...order, status: nextStatus } : order
                )
            );
            alert(`Đã chuyển đơn hàng ${orderId} sang trạng thái ${nextStatus}`);
        } catch (error) {
            console.error('Lỗi cập nhật trạng thái:', error);
            alert('Không thể cập nhật trạng thái. Vui lòng kiểm tra quyền Admin!');
        }
    };


    return (
        <>
            {/* Phần tiêu đề trang giúp căn chỉnh lề chuẩn AdminLTE */}
            <div className="content-header">
                <div className="container-fluid">
                    <div className="row mb-2">
                        <div className="col-sm-6">
                            <h1 className="m-0">Danh sách hóa đơn</h1>
                        </div>
                    </div>
                </div>
            </div>

            {/* Nội dung chính đưa vào section để Sidebar không đè lên */}
            <section className="content">
                <div className="container-fluid">
                    <div className="card">
                        <div className="card-body table-responsive p-0">
                            <table className="table table-hover text-nowrap">
                                <thead>
                                    <tr>
                                        <th>ID</th>
                                        <th>Khách hàng</th>
                                        <th>Tổng tiền</th>
                                        <th>Trạng thái hiện tại</th>
                                        <th>Xử lý chuyển trạng thái</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {orders.length > 0 ? (
                                        orders.map((order) => (
                                            <tr key={order.id}>
                                                <td>{order.id}</td>
                                                <td>{order.userId}</td>
                                                <td>${order.totalAmount?.toFixed(2)}</td>
                                                <td>
                                                    <span className={`badge ${statusMap[order.status]?.color} p-2 text-white`}>
                                                        {statusMap[order.status]?.label}
                                                    </span>
                                                </td>
                                                <td>
                                                    <select
                                                        className="form-control form-control-sm"
                                                        style={{ width: '160px' }}
                                                        value={order.status} // Giá trị lúc này sẽ là "Pending", "Processing",...
                                                        onChange={(e) => updateStatus(order.id, e.target.value)}
                                                    >
                                                        <option value="Pending">Chờ xử lý</option>
                                                        <option value="Processing">Chờ vận chuyển</option>
                                                        <option value="Shipping">Đang vận chuyển</option>
                                                        <option value="Completed">Hoàn thành</option>
                                                        <option value="Cancelled">Hủy đơn</option>
                                                    </select>
                                                </td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr>
                                            <td colSpan="5" className="text-center py-4">Chưa có đơn hàng nào.</td>
                                        </tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            </section>
        </>
    );
};
export default Orders;
